#include <ctype.h>

int word_count(const char *s) {
    int count = 0, in_word = 0;
    while (*s) {
        if (isspace((unsigned char)*s)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            ++count;
        }
        ++s;
    }
    return count;
}

