}

#include <stddef.h>

void str_reverse(char *s) {
    if (!s || !*s) return;
    char *end = s;
    while (*end) ++end;
    --end;
    while (s < end) {
        char tmp = *s;
        *s++ = *end;
        *end-- = tmp;
    }
}

import time

def retry_backoff(fn, retries: int = 5, base_delay: float = 0.5):
    for attempt in range(retries):
        try:
            return fn()
        except Exception:
            if attempt == retries - 1:
                raise
            time.sleep(base_delay * 2 ** attempt)

type RGB = [number, number, number];

export function hexToRgb(hex: string): RGB {
  const clean = hex.replace('#', '');
  const num = parseInt(clean, 16);
  return [(num >> 16) & 0xff, (num >> 8) & 0xff, num & 0xff];
}

#include <algorithm>

template <typename Container, typename T>
bool contains(const Container& c, const T& value) {
    return std::find(std::begin(c), std::end(c), value) != std::end(c);
}

pub fn pad_left(s: &str, width: usize, pad: char) -> String {
    if s.chars().count() >= width {
        return s.to_owned();
    }
    let pad_count = width - s.chars().count();
    std::iter::repeat(pad).take(pad_count).chain(s.chars()).collect()
}

export function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== 'object' || typeof b !== 'object') return false;
  if (a === null || b === null) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  return ka.every(k => deepEqual(a[k], b[k]));
}

import re

def parse_duration(s: str) -> int:
    total = 0
    for value, unit in re.findall(r'(\d+)([smhd])', s):
        multipliers = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400}
        total += int(value) * multipliers[unit]
    return total

